import {OperationalSessionOwner,OPERATIONAL_SESSION_OWNER,OPERATIONAL_SESSION_CONTRACT,OPERATIONAL_SESSION_TAB_POLICY} from './foundation/operational/session-owner.js';
import {OPERATIONAL_TERMINAL_HOST_CONTRACT} from './foundation/operational/terminal-host.js';
import {validateRuntimeAdapterForPresentation,RuntimeAdapterPresentationBoundary} from './foundation/contracts/runtime-adapter.js';
import {BottomDeepWorkOwner} from './foundation/global/bottom-shelf.js';
import {validateBottomDeepWorkProvider} from './foundation/global/bottom-provider-contract.js';
import {WindowMotion} from './foundation/window-motion.js';
import {W03V34RunsAdapter} from './adapters/w03-runs.js';
import {W4FNonDomainRuntimeContractFixture,W4F_CONTRACT_FIXTURE_CLASSIFICATION} from './fixtures/w4-f-runtime-contract-fixture.js';

const assert=(value,message='assertion failed')=>{if(!value)throw Error(message)};
const same=(a,b)=>JSON.stringify(a)===JSON.stringify(b);
const throws=(fn,token)=>{let message='';try{fn()}catch(error){message=String(error?.message||error)}assert(message.includes(token),`expected ${token}, got ${message}`)};
const test=(tests,id,run)=>{try{run();tests.push({id,status:'PASS'})}catch(error){tests.push({id,status:'FAIL',error:String(error?.message||error)})}};

const realFixture=()=>{
  const runtime=new W03V34RunsAdapter();
  const session=runtime.open(runtime.devices[0].id);
  const owner=new OperationalSessionOwner();
  const tab=owner.attachProviderSession(runtime,session.id,{classification:'REAL_RUNTIME_PROVIDER',evidenceRole:'RUNS_W03_V34_GENUINE_PROVIDER'});
  return {runtime,session,owner,tab};
};

export function runW4FOperationalSessionTests(){
  const tests=[];
  test(tests,'w4f.owner-bounded-contract',()=>{const {owner}=realFixture();assert(owner.owner===OPERATIONAL_SESSION_OWNER&&owner.contract===OPERATIONAL_SESSION_CONTRACT);assert(owner.contract.scope==='OPERATIONAL_PRESENTATION_ONLY'&&owner.contract.runtimeTruth==='RuntimeAdapter')});
  test(tests,'w4f.genuine-runs-provider-contract',()=>{const {runtime}=realFixture(),descriptor=validateRuntimeAdapterForPresentation(runtime);assert(descriptor.id==='InternalSimulationAdapter'&&descriptor.sessionOwner==='InternalSimulationAdapter');assert(runtime.lineage==='W03_v3.4'&&runtime.runId==='RUN-0042')});
  test(tests,'w4f.presentation-identity-separate-from-runtime-session',()=>{const {session,tab}=realFixture();assert(tab.runtimeSessionId===session.id);assert(tab.presentationId!==session.id&&tab.presentationId.includes(encodeURIComponent(session.id)));assert(tab.providerSessionOwner==='InternalSimulationAdapter')});
  test(tests,'w4f.live-runtime-read-no-output-cache',()=>{const {runtime,session,owner,tab}=realFixture();const keys=Object.keys(owner);assert(!keys.includes('lines')&&!keys.includes('events')&&!keys.includes('devices')&&!keys.includes('output'));const before=owner.readRuntimeSession(tab.presentationId);assert(before.lines.length===0);runtime.input(session.id,'show status','w4f-live-read-1');const after=owner.readRuntimeSession(tab.presentationId);assert(after.lines.length===1&&after.lines[0].output.includes('UP'));assert(owner.tabsSnapshot()[0].runtimeSessionId===session.id&&!('lines' in owner.tabsSnapshot()[0]))});
  test(tests,'w4f.tab-close-preserves-provider-session',()=>{const {runtime,session,owner,tab}=realFixture();owner.closeTab(tab.presentationId);assert(owner.tabsSnapshot().length===0&&runtime.session(session.id)===session);assert(owner.snapshot().lastTransition.providerSessionPreserved===true)});
  test(tests,'w4f.chrome-close-retains-tabs',()=>{const {owner,tab}=realFixture();owner.closeChrome();assert(owner.snapshot().chrome.lifecycle==='closed'&&owner.tab(tab.presentationId));owner.openChrome();assert(owner.snapshot().chrome.lifecycle==='open')});
  test(tests,'w4f.presentation-routes-reject-runtime-semantics',()=>{const {owner}=realFixture();for(const action of ['runtime.input','runtime.execute','device.shutdown','session.execute'])throws(()=>owner.route(action,{}),'OPERATIONAL_PRESENTATION_ROUTE_OUT_OF_SCOPE')});
  test(tests,'w4f.contract-fixture-is-explicitly-non-domain',()=>{const fixture=new W4FNonDomainRuntimeContractFixture(),owner=new OperationalSessionOwner(),tab=owner.attachProviderSession(fixture,'fixture-session-1',{classification:W4F_CONTRACT_FIXTURE_CLASSIFICATION,evidenceRole:'SHAPE_REUSE_ONLY'}),descriptor=owner.providerDescriptor(fixture.kind);assert(descriptor.classification===W4F_CONTRACT_FIXTURE_CLASSIFICATION&&descriptor.evidenceRole==='SHAPE_REUSE_ONLY');assert(owner.readRuntimeSession(tab.presentationId).lines[0].output==='fixture-source-output');throws(()=>fixture.input(),'CONTRACT_FIXTURE_INPUT_NOT_SUPPORTED')});
  test(tests,'w4f.provider-neutral-shape-reuse',()=>{const real=new W03V34RunsAdapter(),fixture=new W4FNonDomainRuntimeContractFixture(),realBoundary=new RuntimeAdapterPresentationBoundary(real),fixtureBoundary=new RuntimeAdapterPresentationBoundary(fixture),realSession=real.open(real.devices[0].id);assert(realBoundary.readSession(realSession.id).deviceId===realSession.deviceId);assert(fixtureBoundary.readSession('fixture-session-1').deviceId==='fixture-device');assert(typeof realBoundary.descriptor().label==='string'&&typeof fixtureBoundary.descriptor().label==='string')});
  test(tests,'w4f.bottom-deep-work-compatibility-read-only',()=>{const {owner}=realFixture(),provider=owner.asBottomDeepWorkProvider();validateBottomDeepWorkProvider(provider);const bottom=new BottomDeepWorkOwner({providers:[provider]});bottom.open(provider.descriptor().id);const read=bottom.readActiveProvider();assert(read.sourceOwner===OPERATIONAL_SESSION_OWNER&&read.readOnly===true&&read.ownsCanonicalContent===false);assert(read.presentation.tabs.length===1)});
  test(tests,'w4f.window-motion-only-floating',()=>{const {owner,tab}=realFixture();globalThis.innerWidth=1600;globalThis.innerHeight=900;const element={style:{},closest:()=>null,setPointerCapture:()=>{}},event={button:0,target:element,clientX:100,clientY:100,pointerId:7,preventDefault:()=>{}};const motion=new WindowMotion(target=>owner.motionBinding(tab.presentationId,target));assert(motion.down(event)===false);owner.setPlacement('floating');assert(motion.down(event)===true);motion.move({...event,clientX:140,clientY:125});assert(motion.up()===true);const g=owner.snapshot().chrome.geometry;assert(g.x===160&&g.y===165);owner.setPlacement('bottom');assert(owner.motionBinding(tab.presentationId,element)===null)});
  test(tests,'w4f.central-tab-policy-probe',()=>{const runtime=new W03V34RunsAdapter(),sessions=runtime.devices.map(device=>runtime.open(device.id));const normal=new OperationalSessionOwner();const modified=new OperationalSessionOwner({tabPolicy:{...OPERATIONAL_SESSION_TAB_POLICY,revision:'w4f-policy-probe',closeSelection:'LEFT_THEN_RIGHT'}});for(const session of sessions){normal.attachProviderSession(runtime,session.id);modified.attachProviderSession(runtime,session.id)}const normalTabs=normal.tabsSnapshot(),modifiedTabs=modified.tabsSnapshot();normal.selectTab(normalTabs[1].presentationId);modified.selectTab(modifiedTabs[1].presentationId);normal.closeTab(normalTabs[1].presentationId);modified.closeTab(modifiedTabs[1].presentationId);assert(normal.activePresentationId===normalTabs[2].presentationId);assert(modified.activePresentationId===modifiedTabs[0].presentationId);assert(normal.tabPolicy.revision===OPERATIONAL_SESSION_TAB_POLICY.revision&&modified.tabPolicy.revision==='w4f-policy-probe')});
  test(tests,'w4f.terminal-host-contract-denies-interpretation-and-fabrication',()=>{assert(OPERATIONAL_TERMINAL_HOST_CONTRACT.commandInterpretation===false&&OPERATIONAL_TERMINAL_HOST_CONTRACT.outputFabrication===false&&OPERATIONAL_TERMINAL_HOST_CONTRACT.scope==='PRESENTATION_AND_INPUT_FORWARDING_ONLY')});
  test(tests,'w4f.invalid-provider-rejected',()=>{throws(()=>validateRuntimeAdapterForPresentation({descriptor:()=>({contract:{id:'Fake'},id:'x',label:'x'}),session:()=>null}),'INVALID_RUNTIME_ADAPTER_CONTRACT');throws(()=>validateRuntimeAdapterForPresentation({descriptor:()=>({contract:{id:'RuntimeAdapter',version:'1.0.0'},id:'x',label:'x'})}),'RUNTIME_ADAPTER_SESSION_READER_REQUIRED')});
  test(tests,'w4f.default-policy-deterministic',()=>{const a=new OperationalSessionOwner().tabPolicy,b=new OperationalSessionOwner().tabPolicy;assert(same(a,b)&&a.closeSelection==='RIGHT_THEN_LEFT'&&a.reorder==='CLAMPED')});
  return tests;
}
